package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.persistence.mapper.*;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.util.function.ThrowingSupplier;

/** Physical fixed EVAL context. A private complete-read capability is distinct from a
 * current external-processing proof. Expected answers are never prompt context. */
public final class FormalEvaluationContextReads {
 private static final DependencyLineage.Limits LIMITS=new DependencyLineage.Limits(512,2048);
 private static final int MAX=16*1024*1024,TOTAL=64*1024*1024;
 private final JdbcTemplate db;private final PermissionSchema json;private final FormalEvaluationJobs jobs;
 private final FormalEvaluationInputService inputs;private final FormalEvaluationContextStore contexts;
 private final FormalEvaluationContextPackages packages;private final FormalCapabilityIdentityAuthority capabilities;
 private final FormalRuntimeCapabilityIdentityAuthority components;private final AgentExecutionPolicyAuthority policies;
 private final ScopeSnapshotStore scopes;private final DependencyLineage lineage;private final ArtifactRegistryMapper artifacts;
 private final SourceReadAuthority sources;private final TaskFieldSourceAuthority processing;private final SourceUploadTransport transport;
 private final FormalAgentCandidateAuthority candidates;private final EvaluationRuleAuthority rules;private final RunTokenAuthoritySchema roles;
 public FormalEvaluationContextReads(DataSource data,PermissionSchema json,FormalEvaluationJobs jobs,FormalEvaluationInputService inputs,
  FormalEvaluationContextStore contexts,FormalEvaluationContextPackages packages,FormalCapabilityIdentityAuthority capabilities,
  FormalRuntimeCapabilityIdentityAuthority components,AgentExecutionPolicyAuthority policies,ScopeSnapshotStore scopes,
  DependencyLineage lineage,ArtifactRegistryMapper artifacts,SourceReadAuthority sources,TaskFieldSourceAuthority processing,
  SourceUploadTransport transport,EvaluationRuleAuthority rules,RunTokenAuthoritySchema roles,FormalAgentCandidateAuthority candidates){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.json=json;this.jobs=jobs;this.inputs=inputs;this.contexts=contexts;this.packages=packages;this.capabilities=capabilities;this.components=components;this.policies=policies;this.scopes=scopes;this.lineage=lineage;this.artifacts=artifacts;this.sources=sources;this.processing=processing;this.transport=transport;this.rules=rules;this.roles=roles;this.candidates=candidates;}
 private record Source(SourceReadProtocol.ReadRequirement requirement,TaskFieldSourceAuthority.Processing physical){}
 private record Snapshot(FormalEvaluationJobs.Job job,FormalEvaluationJobs.NodeRow node,List<FormalEvaluationContextPackages.Plan> packages,List<Source> sources,JsonNode rules,JsonNode candidate,String witness){}
 public Verified read(FormalEvaluationControlAccess.Reads reads,String step)throws Exception{
  WireValues.uuid(step);EvidenceReadAccess.evaluation(reads).outsideTransaction();var initial=reads.execute(a->ThrowingSupplier.of(()->snapshot(a,reads.runId(),step,null)).get());
  var sample=inputs.readVerified(EvidenceReadAccess.evaluation(reads),reads.contextRevision(),initial.node.node().cell().input().version_id());
  S3ObjectReader.Admission guard=()->reads.execute(a->ThrowingSupplier.of(()->{sample.requireCurrent(a);same(initial.witness,snapshot(a,reads.runId(),step,null).witness);return null;}).get());
  guard.requireCurrent();var content=json.object();content.set("sample",sample.document());content.set("sample_receipt",sample.receipt());content.set("rules",initial.rules.deepCopy());content.set("candidate_manifest",initial.candidate.deepCopy());var payloads=content.putArray("packages");long total=ContentReadAuthorization.canonicalBytes(content).length;
  for(var plan:initial.packages){var actual=packages.read(reads,plan);byte[] bytes=actual.bytes();total+=bytes.length;if(total>TOTAL)limit();var item=payloads.addObject();item.set("receipt",actual.witness());item.put("content_base64",Base64.getEncoder().encodeToString(bytes));guard.requireCurrent();}
  var physical=content.putArray("sources");for(var source:initial.sources){byte[] original=consume(reads,source.physical.original(),guard),parsed=consume(reads,source.physical.parsed(),guard);total+=(long)original.length+parsed.length;if(total>TOTAL)limit();var item=physical.addObject().put("source_version",source.requirement.sourceVersion()).put("parse_version",source.requirement.parseVersion());item.set("original_object",json.tree(source.physical.original()));item.set("parsed_object",json.tree(source.physical.parsed()));item.put("original_base64",Base64.getEncoder().encodeToString(original)).put("parsed_base64",Base64.getEncoder().encodeToString(parsed));}
  guard.requireCurrent();if(ContentReadAuthorization.canonicalBytes(content).length>TOTAL)limit();String id=UUID.randomUUID().toString();var result=new Verified(this,reads,step,initial,content,id);
  reads.execute(a->ThrowingSupplier.of(()->{result.recheck(a,null);record(initial,id,result.pins);result.requireCurrent(a);return null;}).get());return result;
 }
 private Snapshot snapshot(EnterpriseAccess.Admission a,String run,String step,String provider)throws Exception{
  FormalEvaluationExecutionAdmission.current(a);if(!a.evaluationWorker())deny();var job=jobs.byRun(a,run);var node=one(job.nodes().stream().filter(n->n.stepId().equals(step)).toList());var cell=node.node().cell();
  var candidate=candidates.require(a,cell.candidate(),job.projectId(),"AGENT_PUBLICATION");same(cell.runtimeManifestSha256(),candidate.runtimeManifestSha256());
  var admitted=new TaskSourceVerifierSchema().read(job.canonicalAdmission());var approved=contexts.requireApproved(a,basis(admitted.required("context_binding")),cell.candidate(),cell.policy());var binding=approved.node(node.node().nodeKind());same(node.node().role(),binding.role());
  var policy=policies.requireByVersion(a,cell.policy().version_id(),cell.policy().content_sha256(),job.projectId(),job.classification(),"RUN_CREATION");var d=policy.definition();if(d.networkPolicy().externalRequestsAllowed()||!"FIXED_SOURCE_VERSIONS".equals(d.sourceSelection().mode()))deny();
  var role=capabilities.require(a,binding.role(),"ROLE",job.projectId(),"EVALUATION_RESULTS");var prompt=capabilities.require(a,binding.prompt(),"PROMPT",job.projectId(),"EVALUATION_RESULTS");var tool=components.require(a,binding.contextAssembler(),"TOOL",job.projectId(),"EVALUATION_RESULTS");
  var narrowed=roles.read("RoleScope",json.canonical(role.canonicalDefinition().required("request").required("tool_scope")));
  var selection=new CommonProtocol.SourceScope(CommonProtocol.ScopeMode.SOURCE_VERSIONS,List.of(),d.sourceSelection().sources().stream().map(PermissionProtocol.Basis::version_id).sorted().toList(),false,null,null);
  var scope=scopes.readForEvaluation(a,job.projectId(),admitted.required("profile_revision").asText(),selection,cell.evaluationId(),d.businessPurpose(),d.environment(),d.region(),LIMITS,basis(admitted.required("source_snapshot")));
  var roots=new ArrayList<PermissionProtocol.Basis>(List.of(cell.input(),role.sourceArtifact(),prompt.sourceArtifact(),tool.sourceArtifact()));var profile=candidate.runtimeManifest().required("profile").required("artifact");roots.add(new PermissionProtocol.Basis(profile.required("artifact_id").asText(),profile.required("sha256").asText()));if(node.node().tokenizer()!=null)roots.add(node.node().tokenizer());
  // Approved runtime tools and Skills must have real physical package bytes available to their later SDK calls.
  for(String field:List.of("tool_versions","skill_versions"))for(var pin:candidate.manifestDefinition().required(field)){var capability=components.require(a,basis(pin),"tool_versions".equals(field)?"TOOL":"SKILL",job.projectId(),"EVALUATION_RESULTS");roots.add(capability.sourceArtifact());capability.requireUnchanged();}
  var versions=new TreeMap<String,ArtifactRegistryProtocol.VersionRow>();for(var root:roots)for(var v:lineage.inspect(root.version_id(),LIMITS).versions().values()){if(v.projectId()!=null&&!job.projectId().equals(v.projectId()))deny();var old=versions.putIfAbsent(v.id(),v);if(old!=null&&!old.equals(v))bad();}
  var plans=new ArrayList<FormalEvaluationContextPackages.Plan>();var ruleContent=json.object();for(var v:versions.values()){
   if("ARTIFACT".equals(v.entityKind())&&!v.id().equals(cell.input().version_id())){var b=one(artifacts.binding(v.id()));plans.add(packages.plan(a,a.context().context_revision(),job.projectId(),new PermissionProtocol.Basis(v.id(),v.contentSha256()),b.schemaRef(),b.schemaDocumentSha256()));}
   if("RULE_VERSION".equals(v.entityKind())){var rule=rules.require(a,new PermissionProtocol.Basis(v.id(),v.contentSha256()),true);ruleContent.set(v.id(),json.tree(rule));}
  }
  var selected=new HashSet<String>();var actualSources=new ArrayList<Source>();var auth=json.object();for(var member:scope.manifest().members()){
   if(!selected.add(member.source_version()))bad();var req=new SourceReadProtocol.ReadRequirement(member.source_version(),member.rights_revision(),job.projectId(),scope.snapshot().snapshotId(),member.parse_version(),null,provider==null?SourceReadProtocol.Use.FORMAL:SourceReadProtocol.Use.MODEL_SEND,d.businessPurpose(),d.environment(),d.region(),provider);
   var granted=sources.require(a,req);if(provider!=null)for(String action:List.of("source.read","source.external.process")){var permission=json.tree(new RunTokenAuthoritySchema.Permission(new PermissionProtocol.Scope(job.tenantId(),granted.source().ownerProjectId(),"SOURCE",granted.source().sourceId()),action,d.businessPurpose()));boolean found=false;for(var allowed:narrowed.required("permissions"))if(allowed.equals(permission))found=true;if(!found)deny();}
   actualSources.add(new Source(req,processing.processing(job.tenantId(),member.source_version(),member.parse_version(),granted.source().originalSha256())));auth.set(member.source_version(),AgentPublicationWitness.tree(granted));
  }
  // No source ancestor may be smuggled in through a package or rule without a fixed parse/snapshot.
  for(var v:versions.values())if("SOURCE_VERSION".equals(v.entityKind())&&!selected.contains(v.id()))deny();actualSources.sort(Comparator.comparing(s->s.requirement.sourceVersion()));
  var witness=json.object();witness.set("candidate",candidate.manifestDefinition());witness.set("job",json.tree(job));witness.set("versions",json.tree(versions));witness.set("rules",ruleContent);witness.set("scope",json.tree(scope));witness.set("sources",auth);witness.set("physical",json.tree(actualSources));witness.set("role",role.authorizations());witness.set("prompt",prompt.authorizations());witness.set("assembler",tool.authorizations());witness.set("policy",policy.authorizations());
  candidate.requireUnchanged();approved.requireUnchanged();role.requireUnchanged();prompt.requireUnchanged();tool.requireUnchanged();policy.requireUnchanged();return new Snapshot(job,node,List.copyOf(plans),List.copyOf(actualSources),ruleContent,candidate.manifestDefinition(),json.canonical(witness));
 }
 private byte[] consume(FormalEvaluationControlAccess.Reads reads,InterfaceProtocol.ObjectRef ref,S3ObjectReader.Admission guard)throws Exception{
  long size=Long.parseLong(ref.sizeBytes());if(size<1||size>MAX)limit();return transport.readEvaluationDocument(reads,MAX,guard,(reader,lease)->{try(var object=reader.readVerified(ref,lease)){same(ref,object.reference());byte[] bytes=new byte[(int)size];for(int offset=0;offset<bytes.length;){guard.requireCurrent();lease.requireCurrent();int count=Math.min(S3ObjectReader.MAX_SEGMENT_BYTES,bytes.length-offset);byte[] part=object.chunk(offset,count);if(part.length!=count)bad();System.arraycopy(part,0,bytes,offset,count);offset+=count;guard.requireCurrent();}same(ref.sha256(),WireValues.sha256(bytes));same(ref.sha256(),object.fullSha256());return bytes;}});
 }
 public static final class Verified{
  private final FormalEvaluationContextReads owner;private final FormalEvaluationControlAccess.Reads reads;private final String step,id;private final Snapshot original;private final JsonNode content,pins;
  private Verified(FormalEvaluationContextReads owner,FormalEvaluationControlAccess.Reads reads,String step,Snapshot original,JsonNode content,String id)throws Exception{this.owner=owner;this.reads=reads;this.step=step;this.original=original;this.content=content.deepCopy();this.id=id;var p=owner.json.object().put("schema_version","1.0.0").put("kind","EVAL_PHYSICAL_CONTEXT").put("receipt_id",id).put("run_id",reads.runId()).put("step_id",step).put("node_sha256",original.node.nodeSha256()).put("content_sha256",hash(content)).put("authorization_sha256",WireValues.sha256(original.witness.getBytes(java.nio.charset.StandardCharsets.UTF_8)));p.set("content",content.deepCopy());pins=p;}
  private void recheck(EnterpriseAccess.Admission a,String provider)throws Exception{reads.requireActive();same(original.witness,owner.snapshot(a,reads.runId(),step,null).witness);if(provider!=null)owner.snapshot(a,reads.runId(),step,provider);same(hash(content),pins.required("content_sha256").asText());}
  public void requireCurrent(EnterpriseAccess.Admission a)throws Exception{recheck(a,null);owner.registered(original,id,pins);}
  public void requireOriginalPins(EnterpriseAccess.Admission a,JsonNode pins)throws Exception{requireCurrent(a);owner.requirePins(a,reads.runId(),step,pins);same(stableContent(content),stableContent(pins.required("content")));}
  private static JsonNode stableContent(JsonNode content){var copy=(com.fasterxml.jackson.databind.node.ObjectNode)content.deepCopy();copy.remove("sample_receipt");for(var item:copy.required("packages"))((com.fasterxml.jackson.databind.node.ObjectNode)item.required("receipt")).remove("receipt_ids");return copy;}
  public JsonNode requireModelSend(EnterpriseAccess.Admission a,String provider)throws Exception{if(provider==null||provider.isBlank())deny();requireCurrent(a);var sent=owner.snapshot(a,reads.runId(),step,provider);return owner.json.object().put("read_receipt_id",id).put("read_sha256",hash(pins)).put("model_send_authorization_sha256",WireValues.sha256(sent.witness.getBytes(java.nio.charset.StandardCharsets.UTF_8))).put("provider",provider);}
  public JsonNode content(){reads.requireActive();return content.deepCopy();}public JsonNode pins(){reads.requireActive();return pins.deepCopy();}
 }
 public void requirePins(EnterpriseAccess.Admission a,String run,String step,JsonNode pins)throws Exception{
  var current=snapshot(a,run,step,null);same("EVAL_PHYSICAL_CONTEXT",pins.required("kind").asText());same(run,pins.required("run_id").asText());same(step,pins.required("step_id").asText());same(current.node.nodeSha256(),pins.required("node_sha256").asText());same(WireValues.sha256(current.witness.getBytes(java.nio.charset.StandardCharsets.UTF_8)),pins.required("authorization_sha256").asText());same(hash(pins.required("content")),pins.required("content_sha256").asText());registered(current,pins.required("receipt_id").asText(),pins);
 }
 private void record(Snapshot s,String id,JsonNode pins)throws Exception{var j=s.job;String body=json.canonical(pins),digest=hash(pins),audit=UUID.randomUUID().toString(),event=UUID.randomUUID().toString();var now=one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1)));changed(db.update("INSERT INTO audit_event (tenant_id,project_id,audit_id,subject_id,action,resource_ref,result,request_id,trace_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES (?,?,?,?,'evaluation.context.read',?,'SUCCESS',?,?,'1.0.0',?,?,?,?)",j.tenantId(),j.projectId(),audit,j.actorId(),body,id,j.runId(),json.manifestSha256(),j.actorId(),now,j.classification()));changed(db.update("INSERT INTO outbox_event (tenant_id,event_id,aggregate_id,aggregate_revision,event_type,payload,occurred_at) VALUES (?,?,?,1,'evaluation.context.read',?,?)",j.tenantId(),event,id,body,now));changed(db.update("INSERT INTO formal_evaluation_context_read (tenant_id,project_id,run_id,step_id,receipt_id,node_sha256,canonical_receipt,receipt_sha256,audit_id,event_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES (?,?,?,?,?,?,?,?,?,?,'1.0.0',?,?,?,?)",j.tenantId(),j.projectId(),j.runId(),s.node.stepId(),id,s.node.nodeSha256(),body,digest,audit,event,json.manifestSha256(),j.actorId(),now,j.classification()));}
 private void registered(Snapshot s,String id,JsonNode pins)throws Exception{var j=s.job;var row=one(db.queryForList("SELECT * FROM formal_evaluation_context_read WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND receipt_id=? AND created_by=? LIMIT 2",j.tenantId(),j.projectId(),j.runId(),s.node.stepId(),id,j.actorId()));String body=json.canonical(pins);same(body,row.get("canonical_receipt"));same(hash(pins),row.get("receipt_sha256"));same(json.manifestSha256(),row.get("schema_manifest_sha256"));same(body,one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND audit_id=? AND subject_id=? AND action='evaluation.context.read' AND result='SUCCESS' AND request_id=? AND trace_id=?",(r,n)->r.getString(1),j.tenantId(),row.get("audit_id"),j.actorId(),id,j.runId())));same(body,one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND event_type='evaluation.context.read'",(r,n)->r.getString(1),j.tenantId(),row.get("event_id"),id)));}
 private static PermissionProtocol.Basis basis(JsonNode n){return new PermissionProtocol.Basis(n.required("version_id").asText(),n.required("content_sha256").asText());}
 private static String hash(Object o)throws Exception{return WireValues.sha256(ContentReadAuthorization.canonicalBytes(o));}private static <T>T one(List<T> xs){if(xs.size()!=1||xs.get(0)==null)bad();return xs.get(0);}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void changed(int n){if(n!=1)bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}private static void limit(){throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);}
}
